        cs = [c for c in range(w) if sum(grid[r][c] != color for r in range(h)) <= 3]
        if len(rs) >= 2 and len(cs) >= 2:
            divider = color
            break
    if divider is None:
        return [[grid[0][0]]]
    rs = [r for r in range(h) if sum(v != divider for v in grid[r]) <= 3]
    cs = [c for c in range(w) if sum(grid[r][c] != divider for r in range(h)) <= 3]
