        for v in row:
            if v != divider:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    out = []
    for i in range(len(rs) - 1):
        row = []
        for j in range(len(cs) - 1):
            corners = [grid[rs[i]][cs[j]], grid[rs[i]][cs[j+1]],
