 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find near-uniform divider rows/columns, with up to two marker exceptions.
    divider = None
    for color in set(v for row in grid for v in row):
        if any(sum(v != color for v in row) <= 2 for row in grid) and any(sum(grid[r][c] != color for r in range(h)) <= 2 for c in range(w)):
            divider = color
            break
    rs = [r for r in range(h) if sum(v != divider for v in grid[r]) <= 2]
    cs = [c for c in range(w) if sum(grid[r][c] != divider for r in range(h)) <= 2]
    # Output each rectangle between adjacent divider lines: matching four
    # non-divider corner markers keep their color; otherwise use the fill color.
    counts = {}
    for row in grid:
        for v in row:
            if v != divider:
                counts[v] = counts.get(v, 0) + 1
    fill = max(counts, key=counts.get)
    return [[(grid[rs[i]][cs[j]] if grid[rs[i]][cs[j]] != divider and
              grid[rs[i]][cs[j]] == grid[rs[i]][cs[j+1]] == grid[rs[i+1]][cs[j]] == grid[rs[i+1]][cs[j+1]]
              else fill) for j in range(len(cs)-1)] for i in range(len(rs)-1)]
"
}

