 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Divider rows/columns are nearly uniform in the divider color, with
    # at most a few colored corner markers interrupting them.
    colors = {v for row in grid for v in row}
    divider = None
    for color in colors:
        rs = [r for r in range(h) if sum(v != color for v in grid[r]) <= 3]
        cs = [c for c in range(w) if sum(grid[r][c] != color for r in range(h)) <= 3]
        if len(rs) >= 2 and len(cs) >= 2:
            divider = color
            break
    rs = [r for r in range(h) if sum(v != divider for v in grid[r]) <= 3]
    cs = [c for c in range(w) if sum(grid[r][c] != divider for r in range(h)) <= 3]
    counts = {}
    for row in grid:
        for v in row:
            if v != divider:
                counts[v] = counts.get(v, 0) + 1
    fill = max(counts, key=counts.get)
    out = []
    for i in range(len(rs) - 1):
        row = []
        for j in range(len(cs) - 1):
            corners = [grid[rs[i]][cs[j]], grid[rs[i]][cs[j+1]],
                       grid[rs[i+1]][cs[j]], grid[rs[i+1]][cs[j+1]]]
            row.append(corners[0] if corners[0] != divider and len(set(corners)) == 1 else fill)
        out.append(row)
    return out
"
