 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator color is the most frequent color among the exceptionally sparse
    # horizontal and vertical lines (markers interrupt some separator cells).
    divider = None
    for color in sorted({x for row in grid for x in row}):
        rows = [r for r in range(h) if sum(x != color for x in grid[r]) <= 3]
        cols = [c for c in range(w) if sum(grid[r][c] != color for r in range(h)) <= 3]
        if len(rows) >= 2 and len(cols) >= 2:
            divider = color
            break
    rows = [r for r in range(h) if sum(x != divider for x in grid[r]) <= 3]
    cols = [c for c in range(w) if sum(grid[r][c] != divider for r in range(h)) <= 3]
    counts = {}
    for row in grid:
        for x in row:
            if x != divider:
                counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)
    out = []
    for i in range(len(rows)-1):
        outrow = []
        for j in range(len(cols)-1):
            corners = [grid[rows[i]][cols[j]], grid[rows[i]][cols[j+1]],
                       grid[rows[i+1]][cols[j]], grid[rows[i+1]][cols[j+1]]]
            marker = corners[0]
            outrow.append(marker if marker != divider and all(x == marker for x in corners) else background)
        out.append(outrow)
    return out
