    # Divider rows and columns are uniform apart from sparse intersection marks.
    rs = [r for r in range(h) if sum(x != divider for x in grid[r]) <= 2]
    cs = [c for c in range(w) if sum(grid[r][c] != divider for r in range(h)) <= 2]
    nondivider = {x: n for x, n in counts.items() if x != divider}
    fill = max(nondivider, key=nondivider.get)
    out = []
    for i in range(len(rs)-1):
        row = []
