 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the repeated divider color by finding a color that makes several
    # near-uniform horizontal and vertical separator lines.
    divider = None
    for color in sorted({v for row in grid for v in row}):
        rs0 = [r for r in range(h) if sum(v != color for v in grid[r]) <= 2]
        cs0 = [c for c in range(w) if sum(grid[r][c] != color for r in range(h)) <= 2]
        if len(rs0) >= 2 and len(cs0) >= 2:
            divider = color
            break
    rs = [r for r in range(h) if sum(v != divider for v in grid[r]) <= 2]
    cs = [c for c in range(w) if sum(grid[r][c] != divider for r in range(h)) <= 2]
    counts = {}
